import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  mix,
  smoothstep,
  color,
  dot,
  sin,
  fract,
  texture,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, BoxGeometry, DoubleSide } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'collection-card-2';

  // --- dimensions derived from atlas rect aspect (512x320 -> 1.6:1) ---
  const cardW = 2.2;
  const cardH = cardW / 1.6;

  // ---- drop-shadow plane (depth cue behind card) ----
  const shadowGeo = new PlaneGeometry(cardW * 1.08, cardH * 1.08);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.0,
  });
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0.05, -0.06, -0.08);
  root.add(shadowMesh);

  // ---- machined-metal accent bezel (extruded frame) ----
  const frameGeo = new BoxGeometry(cardW + 0.09, cardH + 0.09, 0.05);
  const frameMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    metalness: 0.5,
    roughness: 0.55,
  });
  if ('clearcoat' in frameMat) frameMat.clearcoat = 0.2;
  const frameMesh = new THREE.Mesh(frameGeo, frameMat);
  frameMesh.position.set(0, 0, -0.03);
  root.add(frameMesh);

  // ---- image card surface ----
  const cardGeo = new BoxGeometry(cardW, cardH, 0.02);
  const cardMat = new MeshBasicNodeMaterial({ side: DoubleSide, transparent: true });
  cardMat.colorNode = mix(color(colors.ink), color('#232330'), uv().y);
  cardMat.opacity = 0;
  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0.01);
  root.add(cardMesh);

  let loadedTexture = null;

  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader
      .loadTexture(imageUrl)
      .then((tex) => {
        loadedTexture = tex;

        const uvNode = uv();
        const topTint = color('#22222c');
        const bottomTint = color(colors.ink);
        const grad = mix(bottomTint, topTint, uvNode.y).mul(1.18);

        // procedural grain
        const grainUv = uvNode.mul(600.0);
        const grain = fract(
          sin(dot(grainUv, vec2(12.9898, 78.233))).mul(43758.5453)
        )
          .sub(0.5)
          .mul(0.035);

        // soft vignette to keep the frame the brightest accent
        const edgeX = smoothstep(0.0, 0.14, uvNode.x).mul(
          smoothstep(0.0, 0.14, uvNode.x.oneMinus())
        );
        const edgeY = smoothstep(0.0, 0.14, uvNode.y).mul(
          smoothstep(0.0, 0.14, uvNode.y.oneMinus())
        );
        const vignette = mix(0.82, 1.0, edgeX.mul(edgeY));

        const base = texture(tex, uvNode);

        cardMat.colorNode = base.mul(grad).mul(vignette).add(vec3(grain));
        cardMat.needsUpdate = true;
      })
      .catch(() => {
        // keep engineered gradient fallback if texture fails to load
      });
  }

  // ---- entrance + idle motion ----
  root.scale.set(0.98, 0.98, 0.98);
  const initialY = root.position.y;
  root.position.y -= 0.22;

  const tl = gsap.timeline();
  tl.to(cardMat, { opacity: 1, duration: 0.6, ease: 'power2.out' });
  tl.to(shadowMat, { opacity: 0.4, duration: 0.6, ease: 'power2.out' }, 0);
  tl.to(
    root.position,
    { y: initialY, duration: 0.7, ease: 'power3.out' },
    0
  );
  tl.to(
    root.scale,
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power2.out' },
    0.05
  );
  tl.to(
    root.scale,
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0.55
  );

  // idle breathing (single slow transform, <=2%)
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 1.6 });
  idleTl.to(root.scale, {
    x: 1.015,
    y: 1.015,
    z: 1.015,
    duration: 3.2,
    ease: 'sine.inOut',
  });

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    idleTl.kill();

    cardGeo.dispose();
    cardMat.dispose();
    frameGeo.dispose();
    frameMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }
  };

  return root;
}
